#!/usr/bin/env bash
# Spec-driven, stateful-ish API fuzzing for Valhalla-server using Schemathesis (the lightweight,
# pip-installable alternative to RESTler - no .NET SDK, no compiler step). It reads docs/openapi.json
# directly (regenerated by `cmake --build` / tools/docs/build.sh) and uses Hypothesis to generate
# boundary-value, malformed, and negative test cases per endpoint, then checks responses for server
# errors, schema violations, and other API-contract breaks.
#
# 1. Logs in as a throwaway provider account (created fresh for this run) to get a real JWT, since the
#    spec marks every operation as needing bearerAuth - without a token almost everything just 401s
#    and Schemathesis never gets past the auth wall.
# 2. Runs `st run docs/openapi.json` against the live server with that token on every request.
#
# Usage: ./schemathesis_test.sh
# Env:   BASE_URL      (default http://127.0.0.1:8080/api/v2)
#        SPEC          (default docs/openapi.json, next to this script)
#        OUT_DIR       (default schemathesis-results, next to this script)
#        MAX_EXAMPLES  (default 50)   - test cases generated per endpoint
#        MAX_TIME      (default 300)  - overall time budget in seconds
#        CHECKS        (default all) - comma list, see `st run --help`
#        EXTRA_ARGS    - extra args appended to the `st run` invocation
# Needs: python3, pip-installed `schemathesis` (this script installs it into
#        ~/.local if the `st` command isn't already on PATH).
set -uo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
BASE_URL="${BASE_URL:-http://127.0.0.1:8080/api/v2}"
SPEC="${SPEC:-$ROOT/docs/openapi.json}"
OUT_DIR="${OUT_DIR:-$ROOT/schemathesis-results}"
MAX_EXAMPLES="${MAX_EXAMPLES:-50}"
MAX_TIME="${MAX_TIME:-300}"
CHECKS="${CHECKS:-all}"
# positive_data_acceptance (ST202 "Schema-valid request rejected") assumes a request that matches
# the OpenAPI schema should always be accepted. That holds for pure data-shape validation, but this
# API has business rules no JSON Schema can express - "Delete is NOT implemented for entity type
# ...", "Initial service admin_id and owner_id should be equal to that of provider_id", SQL
# injection pattern detection, and the like - which schemathesis's fuzzer will always eventually
# trip and flag as a false positive. Excluded by default; run with EXCLUDE_CHECKS= (empty) to see them again.
EXCLUDE_CHECKS="${EXCLUDE_CHECKS-positive_data_acceptance}"
EXTRA_ARGS="${EXTRA_ARGS:-}"
# Logout (/clients/{type}/logout) really does kill the session server-side (GateKeeper::logout ->
# SessionManager::removeSession). We log in ONCE and hand Schemathesis that single token for every
# generated test case; if the fuzzer happens to hit logout, every later test case in the run reuses
# the now-dead token and 401s - a cascade of "failures" that are a test-harness artifact, not real
# bugs. Exclude logout from fuzzing (it would need a fresh token per case to be tested meaningfully).
EXCLUDE_PATH_REGEX="${EXCLUDE_PATH_REGEX:-/logout$}"

export PATH="$HOME/.local/bin:$PATH"

if [[ -t 1 ]]; then G=$'\033[32m'; R=$'\033[31m'; Y=$'\033[33m'; B=$'\033[1m'; N=$'\033[0m'; else G=""; R=""; Y=""; B=""; N=""; fi
say()  { printf '%s\n' "$*"; }
note() { printf '%s[*]%s %s\n' "$Y" "$N" "$*"; }
ok()   { printf '%s[+]%s %s\n' "$G" "$N" "$*"; }
err()  { printf '%s[-]%s %s\n' "$R" "$N" "$*" >&2; }

command -v python3 >/dev/null || { err "python3 is required but was not found on PATH"; exit 2; }
[[ -f $SPEC ]] || { err "OpenAPI spec not found: $SPEC (run 'cmake --build' or tools/docs/build.sh to generate it)"; exit 2; }

if ! command -v st >/dev/null; then
	note "schemathesis ('st') not found - installing into ~/.local ..."
	pip3 install --user --quiet schemathesis || { err "pip install schemathesis failed"; exit 2; }
	command -v st >/dev/null || { err "schemathesis installed but 'st' still not on PATH ($HOME/.local/bin)"; exit 2; }
fi

note "Base URL: $BASE_URL"
note "Spec:     $SPEC"
note "Results:  $OUT_DIR"
mkdir -p "$OUT_DIR"

# ---------------------------------------------------------------------------
# 1. Create a throwaway provider and log in to get a real JWT for every request.
# ---------------------------------------------------------------------------
RUN="$$_$RANDOM"
say "${B}== Creating throwaway provider (run $RUN) and logging in ==${N}"
CREATE_BODY=$(cat <<JSON
{"avatar":"http://www.gravatar.com/avatar/205e460b479e2e5b48aec07710c08d50?s=200","active":true,"language":"en","username":"fuzzprov$RUN","password":"1234@Abc!","fullname":"Fuzz Test","phone":"+201299999999","email":"fuzzprov$RUN@mail.com","country":"Egypt","city":"Damietta","address":"portsaid street","dob":"17-02-1985","gender":"Male","position":"Doctor","speciality":"Cardiology"}
JSON
)
CREATE_STATUS=$(curl -s -o /dev/null -w '%{http_code}' -X POST "$BASE_URL/clients/providers/create" \
	-H 'Content-Type: application/json' -d "$CREATE_BODY")
CREATE_STATUS="${CREATE_STATUS:-000}"
if [[ $CREATE_STATUS != 200 && $CREATE_STATUS != 201 ]]; then
	err "Could not create the throwaway account (HTTP $CREATE_STATUS). Is the server running at $BASE_URL ?"
	err "  check with: curl $BASE_URL/hello"
	exit 2
fi

LOGIN_BODY=$(printf '{"username":"fuzzprov%s","password":"1234@Abc!"}' "$RUN")
LOGIN_RESPONSE=$(curl -s -X POST "$BASE_URL/clients/providers/login" -H 'Content-Type: application/json' -d "$LOGIN_BODY")
TOKEN=$(python3 -c "import json,sys; print(json.loads(sys.argv[1]).get('access_token') or json.loads(sys.argv[1]).get('token') or '')" "$LOGIN_RESPONSE" 2>/dev/null)
if [[ -z $TOKEN ]]; then
	err "Login did not return a token. Raw response: $LOGIN_RESPONSE"
	exit 2
fi
ok "Got a token for throwaway provider fuzzprov$RUN"
echo

# ---------------------------------------------------------------------------
# 2. Run Schemathesis against the live server with that token on every request.
# ---------------------------------------------------------------------------
say "${B}== Running Schemathesis (max-examples=$MAX_EXAMPLES, max-time=${MAX_TIME}s, checks=$CHECKS) ==${N}"
# shellcheck disable=SC2086
st run "$SPEC" \
	--url "$BASE_URL" \
	-H "Authorization: Bearer $TOKEN" \
	--checks="$CHECKS" \
	${EXCLUDE_CHECKS:+--exclude-checks="$EXCLUDE_CHECKS"} \
	--max-examples="$MAX_EXAMPLES" \
	--max-time="$MAX_TIME" \
	--exclude-path-regex "$EXCLUDE_PATH_REGEX" \
	--report=junit \
	--report-dir="$OUT_DIR" \
	$EXTRA_ARGS
STATUS=$?

echo
say "Report dir: $OUT_DIR"
note "Note: endpoints that depend on ids created by OTHER endpoints (read/update/delete by id) will mostly"
note "get 404s here, since Schemathesis fuzzes each operation independently rather than chaining create ->"
note "use-the-id -> delete like sqlmap_test.sh's generator does. That's expected, not a bug."
note "Note: /logout endpoints are excluded from fuzzing - they invalidate the one shared token for the"
note "rest of the run, which would otherwise cause a cascade of unrelated 401 \"failures\"."

if ((STATUS != 0)); then
	err "Schemathesis reported failures - see the output above and $OUT_DIR for the JUnit report."
	exit "$STATUS"
fi
ok "No failures reported."
exit 0
